"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[99258],{15598:e=>{e.exports=JSON.parse('{"label":"build","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/tags/build","allTagsPath":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/tags","count":7,"items":[{"id":"version-1.0/build-dapps/create-dapp","title":"Create your first dApp","description":"Once you learned how to run a simple example, it is now time to create one of your own. In order to do this, we will make use of the existing dApps available in Cartesi\'s rollups-examples Github repository. Once again, make sure you have installed all the necessary requirements before proceeding.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/build-dapps/create-dapp"},{"id":"version-1.0/challenges/overview","title":"Current challenges","description":"Cartesi Rollups are shaped by the contributions and collaborative efforts of its decentralized community. As the community continuously works together to build something amazing, there are ongoing challenges that need attention. On this page, you\u2019ll explore these challenges and potential strategies and solutions that the community might consider.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/challenges/overview"},{"id":"version-1.0/build-dapps/requirements","title":"General requirements","description":"To start developing applications using Cartesi Rollups, first make sure that the packages listed in this section are all installed and working in your system. The instructions listed below should be enough to turn a fresh copy of the latest Ubuntu LTS distribution into a fully fledged Cartesi development environment.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/build-dapps/requirements"},{"id":"version-1.0/build-dapps/overview","title":"Overview","description":"Cartesi\'s vision is that creating a dApp should not be too different from the general development of desktop, web, and mobile applications. To that end, Cartesi provides a framework for building decentralized logic, giving developers full flexibility to use the tools and libraries of their preference.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/build-dapps/overview"},{"id":"version-1.0/build-dapps/guidelines","title":"Performance recommendations","description":"The Cartesi Rollups framework offers a plethora of possibilities for developing dApps, giving you the freedom to choose the technologies and stacks that align with your goals. Nonetheless, it is essential to consider certain recommendations to ensure that the dApps work seamlessly, given the current state of the Cartesi Rollups framework.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/build-dapps/guidelines"},{"id":"version-1.0/build-dapps/run-dapp","title":"Run an example dApp","description":"This article explains how to build and interact with a minimalistic Cartesi Rollups application.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/build-dapps/run-dapp"},{"id":"version-1.0/build-dapps/dapp-host-mode","title":"Run back-end in Host Mode","description":"When developing an application, it is often important to easily test and debug it. For that matter, it is possible to run the Cartesi Rollups environment in host mode, so that the dApp\'s back-end can be executed directly on the host machine, allowing it to be debugged using regular development tools such as an IDE.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/build-dapps/dapp-host-mode"}]}')}}]);